const MIN_ACTION_TICK = -1;
const PATH_KEYS = ["top", "middle", "bottom"];
const PATH_INDEX = { top: 0, middle: 1, bottom: 2 };
const PATH_LABELS = { top: "Top", middle: "Middle", bottom: "Bottom" };

