function countPendingVillageFarms(villageId,throughRound=MAX_ROUND){ return state.events.filter(e=>e.type==="absorb"&&e.monkeyId===villageId&&e.absorbMode==="farms"&&e.round<=throughRound).reduce((sum,e)=>sum+(e.absorbedMonkeyIds?.length||0),0); }
function isVillage005UpgradeBlocked(ev,next){ if(ev.towerId!=="monkey-village")return false; const cur=ev.upgrade||ev.snapshotUpgrade||"000"; return Number(cur[2]||0)<5&&Number(next[2]||0)>=5; }
function isVillageBottomDowngradeLocked(ev,path,current){ return ev.towerId==="monkey-village"&&path==="bottom"&&Number(String(current||"000")[2]||0)>=4; }
function selectedTierDecreaseLocked(id,path){ const ev=state.events.find(e=>e.id===id); const current=ev?.upgrade||ev?.snapshotUpgrade||"000"; return !!ev&&isVillageBottomDowngradeLocked(ev,path,current); }
function selectedTierIncreaseLocked(id,path){ const ev=state.events.find(e=>e.id===id); const current=ev?.upgrade||ev?.snapshotUpgrade||"000"; return !!ev&&ev.towerId==="monkey-village"&&path==="bottom"&&Number(String(current||"000")[2]||0)===4; }
function refreshVillageAbsorbTotals(){ Object.values(state.monkeyInstances).forEach(inst=>{ if(inst.towerId==="monkey-village"){ const absorbs=state.events.filter(e=>e.type==="absorb"&&e.monkeyId===inst.id&&e.absorbMode==="farms"); absorbs.forEach(e=>{ e.absorbedMoneySpent=(e.absorbedMonkeyIds||[]).reduce((sum,id)=>sum+calculateTotalSpentOnMonkeyUntilRound(id,e.round),0); }); inst.absorbedFarmMoneySpent=absorbs.reduce((sum,e)=>sum+Number(e.absorbedMoneySpent||0),0); } }); }
function releaseAbsorbedByEvent(eventId){ Object.values(state.monkeyInstances).forEach(inst=>{ if(inst.absorbedBy===eventId)releaseAbsorbedMarker(inst.id); }); }
function releaseAbsorbedByMonkey(monkeyId){ state.events.filter(e=>e.monkeyId===monkeyId&&e.absorbedMonkeyIds).forEach(e=>releaseAbsorbedByEvent(e.id)); }
function releaseAbsorbedMarker(monkeyId){ const inst=state.monkeyInstances[monkeyId]; if(!inst)return; delete inst.absorbedBy; delete inst.absorbedKind; delete inst.absorbedRound; delete inst.absorbedParagonIndex; delete inst.absorbedPending; delete state.paragonHistory[monkeyId]; }

function getMonkeyopolisFarmUpgradeCost(villageId,round=MAX_ROUND){ return countPendingVillageFarms(villageId,round)*priceWithDifficulty(5000); }
function getMonkeyopolisUpgradePrice(villageId,currentUpgrade="000",round=MAX_ROUND){ const next=getMonkeyopolisUpgradeCode(currentUpgrade); return calculateUpgradeCostDelta("monkey-village",currentUpgrade,next)+getMonkeyopolisFarmUpgradeCost(villageId,round); }
function getMonkeyopolisUpgradeCode(currentUpgrade="000"){ const nums=upgradeNums(currentUpgrade); nums[2]=5; return nums.join(""); }
function getVillageAbsorbedFarmSpend(villageId,round=MAX_ROUND){ return state.events.filter(e=>e.type==="absorb"&&e.monkeyId===villageId&&e.absorbMode==="farms"&&e.round<=round).reduce((sum,e)=>sum+Number(e.absorbedMoneySpent||0),0); }
function getMonkeyopolisExtraIncome(villageId,round=MAX_ROUND){ const spent=getVillageAbsorbedFarmSpend(villageId,round); return Math.floor(spent/2000)*200; }
function getMonkeyopolisCrateValue(villageId,round=MAX_ROUND){ return Math.floor((1000+getMonkeyopolisExtraIncome(villageId,round))/10); }
window.upgradeMonkeyopolis=function(villageId){ const inst=state.monkeyInstances[villageId]; if(!inst||inst.towerId!=="monkey-village")return; const selected=state.events.find(e=>e.id===state.selectedEventId); const round=selected?.round||state.settings.roundStart; const cur=getMonkeyStateAtRound(villageId,round); if(!cur.placed||cur.sold){ showToast("Monkeyopolis upgrade needs a live village."); return; } if(countPendingVillageFarms(villageId,round)<1){ showToast("Absorb at least one farm first."); return; } const next=getMonkeyopolisUpgradeCode(cur.upgrade||"000"); if(Number(String(cur.upgrade||"000")[2]||0)>=5){ showToast("This village is already Monkeyopolis."); return; } const ev=makeEvent({monkeyId:villageId,towerId:inst.towerId,round,type:"upgrade",fromUpgrade:cur.upgrade||"000",upgrade:next,source:"manual"}); state.events.push(ev); state.activeRound=round; resetTransientCaches(); const err=validateMonkeyTimeline(villageId); if(err){ state.events=state.events.filter(e=>e.id!==ev.id); resetTransientCaches(); showToast(err); return; } state.selectedEventId=ev.id; state.inspectorTab="action"; document.querySelectorAll("[data-inspector-tab]").forEach(o=>o.classList.toggle("active",o.dataset.inspectorTab==="action")); renderAll(); };
function getGameDifficultyPriceMultiplier(){ return ({Easy:.85,Medium:1,Hard:1.08,Impoppable:1.2,CHIMPS:1.08})[state.settings.gameDifficulty]||1; }
function roundToNearestFive(value){ return Math.round(Number(value||0)/5)*5; }
function priceWithDifficulty(price){ return roundToNearestFive(Number(price||0)*getGameDifficultyPriceMultiplier()); }
function isFinalUpgrade(up){ return String(up||"000").split("").some(v=>v==="5"); }
function upgradeNums(up){ return String(up||"000").split("").map(Number); }
function isUpgradeGreaterOrEqual(next,prev){ const n=upgradeNums(next), p=upgradeNums(prev); return n.every((v,i)=>v>=p[i]); }
function isUpgradeStrictlyGreater(next,prev){ const n=upgradeNums(next), p=upgradeNums(prev); return isUpgradeGreaterOrEqual(next,prev)&&n.some((v,i)=>v>p[i]); }
function getMonkeyTimeline(monkeyId){ if(state.monkeyTimelineCache?.has(monkeyId))return state.monkeyTimelineCache.get(monkeyId); const timeline=state.events.filter(e=>e.monkeyId===monkeyId).sort((a,b)=>a.round-b.round||compareEvents(a,b)); state.monkeyTimelineCache?.set(monkeyId,timeline); return timeline; }
function getPreviousUpgradeBefore(ev){ if(!ev?.monkeyId)return "000"; let up="000"; for(const item of getMonkeyTimeline(ev.monkeyId)){ if(item.id===ev.id)break; if(item.type==="upgrade")up=item.upgrade; if(item.type==="paragon")up="PARAGON"; } return up; }
function validateMonkeyTimeline(monkeyId){ if(!monkeyId)return null; const inst=state.monkeyInstances[monkeyId]; if(!inst)return null; const timeline=getMonkeyTimeline(monkeyId); let placed=false, highest="000", sold=false; for(let i=0;i<timeline.length;i++){ const ev=timeline[i]; if(sold)return "Sell must be the last action for that monkey."; if(["place","place-hero","place-geraldo-item","paragon"].includes(ev.type)){ if(placed&&ev.type==="place")return "Base tower placement cannot be after upgrades."; placed=true; if(ev.type==="paragon")highest="PARAGON"; continue; } if(!placed&&["snapshot","upgrade","sell"].includes(ev.type))return "Action cannot be before that monkey is placed."; if(ev.type==="snapshot"){ const snap=ev.snapshotUpgrade||highest; if(!isUpgradeGreaterOrEqual(snap,highest))return "Nontransformative tower cannot be lower than previous upgrades."; ev.snapshotUpgrade=snap; continue; } if(ev.type==="upgrade"){ if(highest==="PARAGON")return "Cannot upgrade after final paragon upgrade."; if(!isUpgradeStrictlyGreater(ev.upgrade,highest))return "Cannot move or lower an upgrade after a larger upgrade."; if(ev.towerId==="monkey-village"&&Number(highest[2]||0)<5&&Number(ev.upgrade[2]||0)>=5&&countPendingVillageFarms(ev.monkeyId,ev.round)<1)return "Monkeyopolis requires at least one pending absorbed farm."; highest=ev.upgrade; continue; } if(ev.type==="sell"){ sold=true; if(i!==timeline.length-1)return "Sell must be the last action for that monkey."; } } return null; }
function getMonkeyStateAtRound(monkeyId,round){ const key=`${monkeyId}|${round}`; if(state.monkeyStateRoundCache?.has(key))return state.monkeyStateRoundCache.get(key); let placed=false,upgrade="000",sold=false; for(const ev of getMonkeyTimeline(monkeyId)){ if(ev.round>round)break; if(["place","place-hero","place-geraldo-item","paragon"].includes(ev.type)){placed=true;sold=false;if(ev.type==="paragon")upgrade="PARAGON";} if(ev.type==="upgrade"&&placed&&!sold)upgrade=ev.upgrade; if(ev.type==="sell"&&placed)sold=true; } const result={placed,upgrade,sold}; state.monkeyStateRoundCache?.set(key,result); return result; }

function getMonkeyStateAtMoment(monkeyId,round,tick){ const key=`${monkeyId}|${round}|${tick}`; if(state.monkeyStateMomentCache?.has(key))return state.monkeyStateMomentCache.get(key); let placed=false,upgrade="000",sold=false; for(const ev of getMonkeyTimeline(monkeyId)){ if(ev.round>round||(ev.round===round&&ev.tick>tick))break; if(["place","place-hero","place-geraldo-item","paragon"].includes(ev.type)){placed=true;sold=false;if(ev.type==="paragon")upgrade="PARAGON";} if(ev.type==="upgrade"&&placed&&!sold)upgrade=ev.upgrade; if(ev.type==="sell"&&placed)sold=true; } const result={placed,upgrade,sold}; state.monkeyStateMomentCache?.set(key,result); return result; }
function getNextAvailableUpgrade(current,tower,monkeyId,round){ for(const path of PATH_KEYS){ const next=addOneTier(current,path); if(next&&isUpgradePatternAllowed(next,tower)&&wouldNotBreakT5Limit(tower.id,next,monkeyId,round))return next; } return null; }
function addOneTier(up,path){ const d=up.split("").map(Number); const i=PATH_INDEX[path]; if(d[i]>=5)return null; d[i]++; return d.join(""); }
function changeUpgradeTier(up,path,delta){ if(delta>0&&deltaWouldLockCrosspath(up,path,delta))return null; const d=up.split("").map(Number); const i=PATH_INDEX[path]; d[i]+=delta; if(d[i]<0||d[i]>5)return null; return d.join(""); }
function deltaWouldLockCrosspath(up,path,delta){ if(!up||delta<=0)return false; const d=up.split("").map(Number); const i=PATH_INDEX[path]; if(d[i]>0)return false; return d.filter(v=>v>0).length>=2; }
function isUpgradePatternAllowed(up,tower){ const d=up.split("").map(Number); if(d.some(v=>v<0||v>5))return false; if(tower){ for(const p of PATH_KEYS){ if(d[PATH_INDEX[p]]>(tower.maxPathTiers[p]??5))return false; } } const above=d.filter(v=>v>2).length, nonzero=d.filter(v=>v>0).length; if(nonzero>2)return false; if(above>1)return false; return true; }
function wouldNotBreakT5Limit(towerId,up,monkeyId,round){ const d=up.split("").map(Number); for(let i=0;i<3;i++){ if(d[i]===5){ const existing=countT5s(towerId,i,round,monkeyId); if(existing>=getT5Limit(towerId,i))return false; } } return true; }
function countT5s(towerId,pathIdx,round,excludeMonkeyId=null){ return Object.values(state.monkeyInstances).filter(inst=>inst.towerId===towerId&&inst.id!==excludeMonkeyId).filter(inst=>{ const cur=getMonkeyStateAtRound(inst.id,round); return !cur.sold && cur.upgrade?.[pathIdx]==="5"; }).length; }
function allT5sExistBefore(towerId,round){ return [0,1,2].every(i=>countT5s(towerId,i,round,null)>=1); }
function isUpgradeAtLeast(up,min){ if(!min)return false; const d=up.split("").map(Number), m=min.split("").map(Number); return d.some((v,i)=>v>=m[i]&&m[i]>0); }
function hasAnyAvailablePath(t){ return t.enabled&&PATH_KEYS.some(p=>(t.maxPathTiers[p]??0)>0); }
function wouldBreakTowerLimits(towerId){ const total=countTowerLimitOccupants(); if(total>=state.settings.maxTowers)return true; if(towerId==="banana-farm"&&countExistingTower("banana-farm")>=state.settings.maxBananaFarms)return true; if(towerId==="monkey-buccaneer"&&isBoatPlacementUnavailable())return true; return false; }
function isBoatPlacementUnavailable(){ return getBoatSpotLimit()<=0 || countExistingTower("monkey-buccaneer")>=getBoatSpotLimit(); }
function getBoatSpotLimit(){ return getMapBoatSpotLimit()+getLordOfAbyssBoatSpotLimit(); }
function getMapBoatSpotLimit(){ return Math.max(0,Number(state.settings.maxBoatSpots||0)); }
function getLordOfAbyssBoatSpotLimit(){ return Math.max(0,Number(state.settings.lordOfAbyss||0)); }
function countExistingTower(towerId){ return Object.values(state.monkeyInstances).filter(i=>i.towerId===towerId).length; }
function countTowerLimitOccupants(){ return Object.values(state.monkeyInstances).filter(i=>i.kind==="tower"||i.kind==="hero").length; }
function hasHeroPlaced(heroId){ return Object.values(state.monkeyInstances).some(i=>i.kind==="hero"&&i.heroId===heroId); }
function isExistingDragDisabled(inst,round){ if(!inst.absorbedBy)return false; const paragonOrAbsorb=state.events.find(e=>e.id===inst.absorbedBy); const sold=paragonOrAbsorb && state.events.some(e=>e.monkeyId===paragonOrAbsorb.monkeyId&&e.type==="sell"&&e.round<=round); if(inst.absorbedKind==="pending-village"){ const villageState=paragonOrAbsorb?getMonkeyStateAtRound(paragonOrAbsorb.monkeyId,round):null; return !sold && inst.absorbedRound<=round && Number(villageState?.upgrade?.[2]||0)>=5; } return !sold && inst.absorbedRound<=round; }
function isEventAtOrBeforeMoment(e,round,tick){ return e.round<round || (e.round===round && e.tick<=tick); }
function calculateTotalSpentOnMonkeyUntilMoment(monkeyId,round,tick=TICKS_PER_ROUND){ return state.events.filter(e=>e.monkeyId===monkeyId&&e.type!=="sell"&&isEventAtOrBeforeMoment(e,round,tick)).reduce((s,e)=>s+Math.max(0,-getMoneyDelta(e,e.round)),0); }
function calculateMoneyGeneratedByMonkeyUntilMoment(monkeyId,round,tick=TICKS_PER_ROUND){ let total=state.events.filter(e=>e.monkeyId===monkeyId&&isEventAtOrBeforeMoment(e,round,tick)&&!["sell","bank-collect","bank-deposit"].includes(e.type)).reduce((s,e)=>s+Math.max(0,getMoneyDelta(e,e.round)),0); for(let r=state.settings.roundStart;r<=round;r++){ const through=r===round?tick:TICKS_PER_ROUND; total+=getTowerIncomeForRound(r).filter(item=>item.inst.id===monkeyId&&item.tick<=through).reduce((s,item)=>s+item.amount,0); } total+=getBankStateAtMoment(monkeyId,round,tick).interestGenerated||0; return total; }
function getBankEndStateForRound(monkeyId,round){ let money=Number(state.settings.startingCash||0), bankState={}; for(let r=state.settings.roundStart;r<=round;r++){ const result=simulateRoundMoney(r,money,null,true,bankState); money=result.money; bankState=result.bankState; } return cloneBankState(bankState)[monkeyId]||{bankMoney:0,eligibleInterest:0,depositedPrincipal:0,interestGenerated:0}; }
function calculateSellValue(monkeyId,round,tick=TICKS_PER_ROUND){ const inst=state.monkeyInstances[monkeyId]; if(!inst)return 0; const rate=getSellbackRate(inst,round,tick); return Math.floor(calculateTotalSpentOnMonkeyUntilMoment(monkeyId,round,tick)*rate)+getBankStateAtMoment(monkeyId,round,tick).bankMoney; }
function calculateTotalSpentOnMonkeyUntilRound(monkeyId,round){ return calculateTotalSpentOnMonkeyUntilMoment(monkeyId,round,TICKS_PER_ROUND); }
function calculateMoneyGeneratedByMonkeyUntilRound(monkeyId,round){ return calculateMoneyGeneratedByMonkeyUntilMoment(monkeyId,round,TICKS_PER_ROUND); }
function isMonkeyKnowledgeEnabled(){ return !!state.settings.monkeyKnowledge; }
function getSellbackRate(inst,round=null,tick=TICKS_PER_ROUND){ if(!isMonkeyKnowledgeEnabled())return inst.kind==="tower"?(getTower(inst.towerId)?.sellbackRate??.70):.70; let rate=.75; if(inst.kind==="tower"&&(inst.towerId==="banana-farm"||inst.towerId==="monkey-village")){ const cur=round===null?null:getMonkeyStateAtMoment(inst.id,round,tick); if(!cur||cur.upgrade==="000")rate+=.02; } return rate; }
function priceWithDifficultyFromRaw(price){ return priceWithDifficulty(Math.max(0,price)); }
function applyFlatDiscount(price,amount){ return Math.max(0,Number(price||0)-Number(amount||0)); }
function getBuffMoment(buff){ return {round:Number(buff.appliedRound||state.settings.roundStart),tick:Number(buff.appliedTick??MIN_ACTION_TICK)}; }
function isMomentAtOrAfter(round,tick,moment){ return round>moment.round || (round===moment.round&&tick>=moment.tick); }
function getActiveSourceBuffs(targetMonkeyId,round,tick,sourceTowerId=null){ return getBuffsForMonkey(targetMonkeyId).filter(buff=>{ if(!isMomentAtOrAfter(round,tick,getBuffMoment(buff)))return false; const src=state.monkeyInstances[buff.sourceMonkeyId]; if(!src||src.kind!=="tower")return false; if(sourceTowerId&&src.towerId!==sourceTowerId)return false; const cur=getMonkeyStateAtMoment(src.id,round,tick); return cur.placed&&!cur.sold&&cur.upgrade!=="PARAGON"; }); }
function getActiveVillageBuffsForEvent(ev){ if(!ev?.monkeyId)return []; return getActiveSourceBuffs(ev.monkeyId,ev.round,ev.tick,"monkey-village").map(buff=>({...buff,sourceUpgrade:getMonkeyStateAtMoment(buff.sourceMonkeyId,ev.round,ev.tick).upgrade})); }
function isPrimaryFreeUpgrade(towerId,code,ev){ const tower=getTower(towerId); if(!tower||tower.category!=="Primary"||!ev)return false; const tier=Math.max(...upgradeNums(code)); if(tier<1||tier>2)return false; return getActiveVillageBuffsForEvent(ev).some(b=>Number(b.sourceUpgrade[0]||0)>=4 && tier<= (Number(b.sourceUpgrade[0]||0)>=5?2:1)); }
function getVillageDiscountMultiplier(towerId,code,ev,isPlacement=false){ if(!ev?.monkeyId)return 1; const tower=getTower(towerId); if(!tower||tower.category==="hero")return 1; const tier=isPlacement?0:Math.max(...upgradeNums(code)); if(tier>3)return 1; const buffs=getActiveVillageBuffsForEvent(ev).filter(b=>Number(b.sourceUpgrade[2]||0)>=1); if(!buffs.length)return 1; const base=buffs.some(b=>Number(b.sourceUpgrade[2]||0)>=1)?(isMonkeyKnowledgeEnabled()?.88:.90):1; const markets=Math.min(3,buffs.filter(b=>Number(b.sourceUpgrade[2]||0)>=2).length); const extra=.05*markets; const totalDiscount=Math.min(isMonkeyKnowledgeEnabled()?.27:.25,(1-base)+extra); return Math.max(0,1-totalDiscount); }
function isFreeMonkeyCityDart(towerId,ev){ if(towerId!=="dart-monkey"||!ev||ev.__skipFreeDart)return false; const active=getActiveSourceBuffs(ev.monkeyId,ev.round,ev.tick,"monkey-village").filter(b=>Number(getMonkeyStateAtMoment(b.sourceMonkeyId,ev.round,ev.tick).upgrade[2]||0)>=4); if(!active.length)return false; const used=state.events.filter(e=>e.type==="place"&&e.towerId==="dart-monkey"&&e.round===ev.round&&e.id!==ev.id&&isEventBefore(e,ev)&&getTowerPlacementCost(e.towerId,{...e,__skipFreeDart:true})===0).length; return used<active.length; }
function applyMonkeyCityIncomeBuff(monkeyId,amount,round,tick,includeAbility=false){ if(!monkeyId||!amount)return amount; const has=getActiveSourceBuffs(monkeyId,round,tick,"monkey-village").some(b=>Number(getMonkeyStateAtMoment(b.sourceMonkeyId,round,tick).upgrade[2]||0)>=4); return has?amount*1.2:amount; }
function countLiveUpgrades(towerId,predicate,round,tick){ return Object.values(state.monkeyInstances).filter(inst=>inst.kind==="tower"&&inst.towerId===towerId).filter(inst=>{ const cur=getMonkeyStateAtMoment(inst.id,round,tick); return cur.placed&&!cur.sold&&cur.upgrade!=="PARAGON"&&predicate(cur.upgrade,inst); }).length; }
function getBuffedTowerIncome(inst,upgrade,amount,round,tick,endIncome=false){ let out=amount; if(inst.towerId==="banana-farm"&&Number(upgrade[0]||0)===4&&countLiveUpgrades("banana-farm",up=>Number(up[0]||0)>=5,round,tick)>0)out*=1.25; if(inst.towerId==="monkey-buccaneer"&&Number(upgrade[2]||0)>=3){ const farmMarkets=Math.min(10,countLiveUpgrades("banana-farm",up=>Number(up[2]||0)>=4,round,tick)); out*=1+farmMarkets/10; } return out; }
function applyTradeEmpireBoatEndIncome(items,round){ const hasEmpire=countLiveUpgrades("monkey-buccaneer",up=>Number(up[2]||0)>=5,round,TICKS_PER_ROUND)>0; if(!hasEmpire)return; const candidates=items.filter(item=>item.inst.towerId==="monkey-buccaneer"&&isTowerEndIncomeEntry(item.entry)).filter(item=>{ const up=getMonkeyStateAtMoment(item.inst.id,round,TICKS_PER_ROUND).upgrade; return Number(up[2]||0)===3||Number(up[2]||0)===4; }); const sorted=candidates.sort((a,b)=>{ const au=getMonkeyStateAtMoment(a.inst.id,round,TICKS_PER_ROUND).upgrade, bu=getMonkeyStateAtMoment(b.inst.id,round,TICKS_PER_ROUND).upgrade; return (Number(bu[2]||0)===4)-(Number(au[2]||0)===4)||a.inst.id.localeCompare(b.inst.id); }); const affected=sorted.slice(0,20); const bonus=Math.min(200,affected.length*10); affected.forEach(item=>item.amount+=bonus); }
function isIMFLoanAbility(ev){ const cur=ev?.monkeyId?getMonkeyStateAtMoment(ev.monkeyId,ev.round,ev.tick):null; return ev?.abilityId==="bank-loan"&&cur&&Number(String(cur.upgrade||"000")[1]||0)===4; }
function getLoanDebtAmount(){ return isMonkeyKnowledgeEnabled()?10000:9000; }
function getLoanRepaymentRate(){ return isMonkeyKnowledgeEnabled() ? .4 : .5; }
function getActiveLoan(bankState){ bankState.__loans=(bankState.__loans||[]).filter(l=>Number(l.remaining||0)>0); return bankState.__loans[0]||null; }
function addLoanDebt(bankState,ev){ bankState.__loans=bankState.__loans||[]; const amount=getLoanDebtAmount(); const loan={id:`loan-${ev.id}`,remaining:amount,originalAmount:amount,monkeyId:ev.monkeyId,round:ev.round,tick:ev.tick}; bankState.__loans.push(loan); return loan; }
function processLoanRepayment(amount,bankState){ amount=Number(amount||0); if(amount<=0)return {received:amount,paidAmount:0,paidLoan:null}; const loan=getActiveLoan(bankState); if(!loan)return {received:amount,paidAmount:0,paidLoan:null}; const take=Math.min(Number(loan.remaining||0),amount*getLoanRepaymentRate()); loan.remaining-=take; const paidLoan=loan.remaining<=0?{...loan,remaining:0}:null; if(paidLoan)bankState.__loans=(bankState.__loans||[]).filter(l=>l!==loan&&Number(l.remaining||0)>0); return {received:amount-take,paidAmount:take,paidLoan}; }
function applyLoanRepayment(amount,bankState){ return processLoanRepayment(amount,bankState).received; }
function loanActionTitle(ev){ return `Active IMF loan from round ${ev.sourceRound} tick ${ev.sourceTick}. ${formatMoney(ev.remaining)} debt remaining before this loan action. Income keeps ${Math.round((1-getLoanRepaymentRate())*100)}% while the rest repays this loan.`; }
function getLoanActionEventsForRound(round){ const key=`${round}|${state.events.length}|${state.settings.monkeyKnowledge?1:0}|${state.settings.startingCash}`; if(state.loanActionCache?.has(key))return state.loanActionCache.get(key); let money=Number(state.settings.startingCash||0), bankState={}, actions=[]; const seen=new Set(); const record=info=>{ if(info.type!=="active"||!info.loan)return; const tick=clamp(Number(info.tick),MIN_ACTION_TICK,TICKS_PER_ROUND); const id=`loan-action-${info.loan.id}-${round}-${tick}`; if(seen.has(id))return; seen.add(id); actions.push({id,round,tick,sortOrder:-1000+actions.length,type:"loan-repayment",source:"generated",monkeyId:info.loan.monkeyId,towerId:"banana-farm",remaining:Number(info.loan.remaining||0),originalAmount:Number(info.loan.originalAmount||0),sourceRound:info.loan.round,sourceTick:info.loan.tick}); }; for(let r=state.settings.roundStart;r<=round;r++){ const result=simulateRoundMoney(r,money,null,true,bankState,{expandTowerIncome:r===state.activeRound,onLoanAction:r===round?record:null}); money=result.money; bankState=result.bankState; } actions=actions.filter(a=>a.remaining>0).sort(compareEvents); state.loanActionCache?.set(key,actions); return actions; }

function getTowerPlacementCost(towerId,ev){ const tower=getTower(towerId); let price=Number(tower?.baseCost||0); if(isMonkeyKnowledgeEnabled()){ if(towerId==="boomerang")price=applyFlatDiscount(price,50); if(tower?.category==="Military")price*=isFirstMilitaryMonkey(towerId,ev)?.62:.95; if(towerId==="banana-farm"||towerId==="monkey-village")price*=.98; if(isFirstPlacedTowerOfType(towerId,ev,"spike-factory"))price=applyFlatDiscount(price,150); if(isFirstPlacedTowerOfType(towerId,ev,"banana-farm"))price=applyFlatDiscount(price,100); if(isFirstFreeDartOrGlue(towerId,ev))price=0; } if(isFreeMonkeyCityDart(towerId,ev))price=0; price*=getVillageDiscountMultiplier(towerId,"000",ev,true); return priceWithDifficultyFromRaw(price); }
function getHeroPlacementCost(heroId,ev){ let price=Number(getHero(heroId)?.baseCost||0); if(isMonkeyKnowledgeEnabled())price*=.9; return priceWithDifficultyFromRaw(price); }
function isFirstPlacedTowerOfType(towerId,ev,typeId){ if(towerId!==typeId)return false; const currentId=ev?.monkeyId||null; return !state.events.some(e=>e.type==="place"&&e.towerId===typeId&&e.monkeyId!==currentId&&isEventBefore(e,ev)); }
function isFirstFreeDartOrGlue(towerId,ev){ if(towerId!=="dart-monkey"&&towerId!=="glue-gunner")return false; const currentId=ev?.monkeyId||null; return !state.events.some(e=>e.type==="place"&&(e.towerId==="dart-monkey"||e.towerId==="glue-gunner")&&e.monkeyId!==currentId&&isEventBefore(e,ev)); }
function isFirstMilitaryMonkey(towerId,ev){ if(getTower(towerId)?.category!=="Military")return false; const currentId=ev?.monkeyId||null; return !state.events.some(e=>e.type==="place"&&getTower(e.towerId)?.category==="Military"&&e.monkeyId!==currentId&&isEventBefore(e,ev)); }
function isEventBefore(candidate,ev){ if(!ev)return true; return candidate.round<ev.round || (candidate.round===ev.round&&compareEvents(candidate,ev)<0); }
function getUpgradeRawCostForMK(towerId,code,ev){ let price=Number(getTower(towerId)?.upgradeCosts?.[code]||0); if(isMonkeyKnowledgeEnabled()){ if(towerId==="bomb-shooter"&&code==="003")price=applyFlatDiscount(price,100); if(towerId==="glue-gunner"&&code==="400")price=applyFlatDiscount(price,1000); if(towerId==="sniper-monkey"&&code==="400")price=applyFlatDiscount(price,1000); if(towerId==="mortar-monkey"&&code==="040")price=applyFlatDiscount(price,600); if(towerId==="wizard-monkey"&&(code==="100"||code==="001"))price=applyFlatDiscount(price,25); if(towerId==="ninja-monkey"&&code==="300")price=applyFlatDiscount(price,100); if(towerId==="druid"&&code==="020")price=applyFlatDiscount(price,100); if(towerId==="spike-factory"&&code==="400")price=applyFlatDiscount(price,1500); if(towerId==="monkey-ace"&&code.includes("5"))price*=.9; if(isPrimaryTierThreeFourDiscountActive(towerId,code,ev))price*=.95; } if(isPrimaryFreeUpgrade(towerId,code,ev))price=0; price*=getVillageDiscountMultiplier(towerId,code,ev,false); return price; }
function calculateUpgradeCostDeltaForEvent(towerId,fromUpgrade="000",toUpgrade="000",ev=null){ const tower=getTower(towerId); if(!tower||fromUpgrade==="PARAGON"||toUpgrade==="PARAGON")return 0; const from=upgradeNums(fromUpgrade), to=upgradeNums(toUpgrade); let total=0; for(let path=0;path<3;path++){ for(let tier=from[path]+1;tier<=to[path];tier++){ const code=[0,0,0]; code[path]=tier; total+=priceWithDifficultyFromRaw(getUpgradeRawCostForMK(towerId,code.join(""),ev)); } } return total; }
function isPrimaryTierThreeFourDiscountActive(towerId,code,ev){ const tower=getTower(towerId); if(!tower||tower.category!=="Primary")return false; const codeTier=Math.max(...upgradeNums(code)); if(codeTier!==3&&codeTier!==4)return false; if(!ev)return false; const after=ev.upgrade||code; return Object.values(state.monkeyInstances).every(inst=>{ if(inst.kind!=="tower"||getTower(inst.towerId)?.category!=="Primary")return true; let up=getMonkeyStateAtMoment(inst.id,ev.round,ev.tick).upgrade; if(inst.id===ev.monkeyId)up=after; const highest=Math.max(...upgradeNums(up||"000")); return highest===3||highest===4; }); }
function getHeroLevelMoneySpent(ev){ const spent=Number(ev.moneySpent||0); return isMonkeyKnowledgeEnabled()?Math.floor(spent*.9):spent; }
function getAbilityMoneyDelta(ev){ let amount=0; if(ev.abilityId==="support-chinook")amount=Math.floor(1800*(isMonkeyKnowledgeEnabled()?1.25:1)); else if(ev.abilityId==="bank-loan")amount=isIMFLoanAbility(ev)?(isMonkeyKnowledgeEnabled()?10000:9000):(isMonkeyKnowledgeEnabled()?10000:9000); else if(ev.abilityId==="supply-drop")amount=1200; else amount=Number(ev.amount||0); return applyMonkeyCityIncomeBuff(ev.monkeyId,amount,ev.round,ev.tick,true); }
function canBankTakeDeposits(upgrade){ return isMonkeyKnowledgeEnabled()&&Number(String(upgrade||"000")[1]||0)>=4; }

function calculateUpgradeCostDelta(towerId,fromUpgrade="000",toUpgrade="000"){ return calculateUpgradeCostDeltaForEvent(towerId,fromUpgrade,toUpgrade,null); }
function getBuffsForMonkey(id){return state.buffs.filter(b=>b.targetMonkeyId===id)}
function compareEvents(a,b){ if(a.tick!==b.tick)return a.tick-b.tick; const order={"place":0,"place-hero":0,"place-geraldo-item":0,"snapshot":1,"upgrade":2,"hero-level":2,"bank-deposit":3,"bank-collect":4,"ability":5,"absorb":6,"paragon":7,"pop-income":8,"round-pop-income":8,"tower-income":8,"loan-repayment":8.5,"sell":9}; return (order[a.type]??9)-(order[b.type]??9)||a.sortOrder-b.sortOrder; }
function isSpecialEvent(e){return ["bank-collect","bank-deposit","absorb","paragon","ability","hero-level","pop-income","tower-income","round-pop-income","loan-repayment"].includes(e.type)}
function getTower(id){return window.BTD6_TOWERS.find(t=>t.id===id)} function getHero(id){return window.BTD6_HEROES.find(h=>h.id===id)} function getSelectedHero(){return getHero(state.settings.selectedHero)} function getGeraldoItem(id){return window.BTD6_GERALDO_ITEMS.find(i=>i.id===id)}
function getInstanceMeta(inst,round=state.endRound){ if(inst.kind==="hero")return {iconKey:getHero(inst.heroId).iconKey,typeLabel:"Hero",category:"hero",absorbedVisible:false}; if(inst.kind==="geraldo-item")return {iconKey:getGeraldoItem(inst.itemId).iconKey,typeLabel:"Geraldo Item",category:"hero",absorbedVisible:false}; if(inst.kind==="paragon")return {iconKey:"paragon",typeLabel:"Paragon",category:"hero",absorbedVisible:false}; const t=getTower(inst.towerId); const visible=!!inst.absorbedBy && isExistingDragDisabled(inst,round); const absorbEvent=inst.absorbedBy?state.events.find(e=>e.id===inst.absorbedBy):null; const released=absorbEvent&&state.events.some(e=>e.monkeyId===absorbEvent.monkeyId&&e.type==="sell"&&e.round<=round); const absorbedText=inst.absorbedBy&&!released?`${inst.absorbedKind==="pending-village"?"pending absorb":"absorbed "+inst.absorbedKind}`:""; return {iconKey:t.iconKey,typeLabel:t.category,category:t.category,absorbedVisible:visible,absorbedText}; }
function getHelperMeta(ev){ if(ev.type==="pop-income"||ev.type==="tower-income"||ev.type==="round-pop-income")return {iconKey:"popIncome",category:"helper"}; if(ev.type==="loan-repayment")return {iconKey:"money",category:"helper"}; return {iconKey:"item",category:"helper"}; }
function formatMoney(v){return `$${Math.round(Number(v||0)).toLocaleString()}`}
function makeId(prefix,n){return `${prefix}-${n}`} function clamp(v,min,max){return Math.max(min,Math.min(max,v))}
function showToast(msg){ el.toast.textContent=msg; el.toast.classList.remove("hidden"); clearTimeout(showToast.t); showToast.t=setTimeout(()=>el.toast.classList.add("hidden"),2300); }
function toggleWipInfo(){ if(!el.wipInfoPanel)return; el.wipInfoPanel.classList.toggle("hidden"); }
function hideWipInfo(){ el.wipInfoPanel?.classList.add("hidden"); }

const tutorialSteps=[
  {target:"header",title:"OptimalBtd6",text:"This top bar is where future calculators can live. Farming Planner is the active one right now."},
  {target:"left-panel",title:"Planner Setup",text:"Set the event type, goal, round start, cash, map difficulty, players, hero, and tower limits here."},
  {target:"right-panel",title:"Available / Existing / Rules",text:"Drag available cards into rounds, reuse existing monkeys for upgrades, and limit tower paths in Rules."},
  {target:"round-map",title:"Round Map",text:"Every important choice becomes a tick-sorted action: placements, upgrades, sells, bank actions, absorbs, abilities, paragons, and pop-income movement."},
  {target:"inspector",title:"Selected Action",text:"Click an action to edit its tick, upgrade tiers, special sub-actions, buffs, or delete/sell it."}
];
function startTutorial(){ state.tutorialIndex=0; showTutorialStep(); }
function showTutorialStep(){ const step=tutorialSteps[state.tutorialIndex]; if(!step){endTutorial();return;} const target=document.querySelector(`[data-tutorial='${step.target}']`); el.tutorialOverlay.classList.remove("hidden"); if(target){ target.scrollIntoView({block:"nearest",inline:"nearest"}); requestAnimationFrame(()=>positionTutorialHighlight(target)); } else { positionTutorialHighlight(null); } el.tutorialTitle.textContent=step.title; el.tutorialText.textContent=step.text; el.tutorialNext.textContent=state.tutorialIndex===tutorialSteps.length-1?"Finish":"Next"; }
function positionTutorialHighlight(target){ if(!el.tutorialHighlight)return; if(!target){ el.tutorialHighlight.style.display="none"; return; } const r=target.getBoundingClientRect(); el.tutorialHighlight.style.display="block"; el.tutorialHighlight.style.left=`${Math.max(8,r.left-6)}px`; el.tutorialHighlight.style.top=`${Math.max(8,r.top-6)}px`; el.tutorialHighlight.style.width=`${Math.min(window.innerWidth-16,r.width+12)}px`; el.tutorialHighlight.style.height=`${Math.min(window.innerHeight-16,r.height+12)}px`; }
function nextTutorialStep(){ state.tutorialIndex++; showTutorialStep(); }
function endTutorial(){ positionTutorialHighlight(null); el.tutorialOverlay.classList.add("hidden"); }

init();
